mapper.select:
SELECT id, order_id, status, retry_count, next_retry_at, last_error, created_at, updated_at
FROM order_compensation
WHERE order_id = #{orderId}

SELECT id, order_id, status, retry_count, next_retry_at, last_error, created_at, updated_at
FROM order_compensation
WHERE status = 'PENDING' AND next_retry_at <= #{now}
ORDER BY next_retry_at
LIMIT #{limit}

mapper.update:
UPDATE order_compensation
SET status = 'DONE', last_error = NULL, updated_at = #{now}
WHERE id = #{id}

UPDATE order_compensation
SET retry_count = #{retryCount}, next_retry_at = #{nextRetryAt}, last_error = #{lastError},
    updated_at = #{now}
WHERE id = #{id}

UPDATE order_compensation
SET status = 'DEAD', last_error = #{lastError}, updated_at = #{now}
WHERE id = #{id}
